import sys
sys.setrecursionlimit(10000)
def comps(g):
    seen=[[False]*len(g[0]) for _ in g]; out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if not seen[r][c] and g[r][c]==0:
                stack=[(r,c)]; seen[r][c]=True; s=[]
                cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<len(g) and 0<=b<len(g[0]) and not seen[a][b] and g[a][b]==0:
                            seen[a][b]=True; stack.append((a,b))
                out.append(cells)
    return out
